def shipping_fee(weight_grams, expedited=False):
    if type(weight_grams) is not int or type(expedited) is not bool:
        raise TypeError
    if weight_grams < 1 or weight_grams > 6000:
        raise ValueError

    extra = max(0, (weight_grams - 1000) // 1000)
    return 600 + extra * 200 + (400 if expedited else 0)

import unittest
from shipping import shipping_fee

class ShippingTests(unittest.TestCase):
    def test_first(self):
        self.assertEqual(shipping_fee(1000), 600)
    def test_whole_step(self):
        self.assertEqual(shipping_fee(2000), 800)
    def test_started_step(self):
        self.assertEqual(shipping_fee(1001), 800)

if __name__ == "__main__":
    unittest.main()

from shipping import shipping_fee

def quote(weight_grams, expedited=False):
    return shipping_fee(weight_grams)

import unittest
from checkout import quote

class CheckoutTests(unittest.TestCase):
    def test_standard(self):
        self.assertEqual(quote(1000), 600)

    def test_expedited(self):
        self.assertEqual(quote(1000, True), 1000)

